BEGIN;
CREATE TABLE IF NOT EXISTS profiles(id text PRIMARY KEY,email text NOT NULL UNIQUE,name text NOT NULL,role text NOT NULL DEFAULT 'member' CHECK(role IN ('member','owner','buyer','partner','staff','super_admin')),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),company text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',country text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS listings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id text NOT NULL REFERENCES profiles(id),title text NOT NULL,commodity text NOT NULL,country text NOT NULL,location text NOT NULL,description text NOT NULL,transaction_type text NOT NULL CHECK(transaction_type IN ('Full sale','Partial stake','Joint venture','Offtake')),asking_price numeric(18,2) CHECK(asking_price>0),currency text NOT NULL DEFAULT 'USD' CHECK(currency IN ('USD','ZAR','LSL')),area_hectares numeric CHECK(area_hectares>0),right_reference text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','changes_requested','approved','under_offer','sold','withdrawn')),review_notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS listings_status ON listings(status,created_at DESC);
CREATE INDEX IF NOT EXISTS listings_owner ON listings(owner_id);
CREATE TABLE IF NOT EXISTS documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),listing_id uuid REFERENCES listings(id) ON DELETE CASCADE,owner_id text NOT NULL REFERENCES profiles(id),name text NOT NULL,kind text NOT NULL CHECK(kind IN ('title','mandate','technical','company','photo','other')),pathname text NOT NULL UNIQUE,size bigint NOT NULL CHECK(size BETWEEN 1 AND 20971520),content_type text NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','ready','deleted')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS document_grants(document_id uuid NOT NULL REFERENCES documents(id) ON DELETE CASCADE,user_id text NOT NULL REFERENCES profiles(id),granted_by text NOT NULL REFERENCES profiles(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(document_id,user_id));
CREATE TABLE IF NOT EXISTS offers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),listing_id uuid NOT NULL REFERENCES listings(id),buyer_id text NOT NULL REFERENCES profiles(id),amount numeric(18,2) NOT NULL CHECK(amount>0),currency text NOT NULL CHECK(currency IN ('USD','ZAR','LSL')),message text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined','withdrawn','completed','cancelled')),stage text NOT NULL DEFAULT 'Offer received' CHECK(stage IN ('Offer received','Due diligence','Agreements','Regulatory approvals','Closing','Completed','Cancelled')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_accepted_offer ON offers(listing_id) WHERE status='accepted';
CREATE UNIQUE INDEX IF NOT EXISTS one_pending_buyer_offer ON offers(listing_id,buyer_id) WHERE status='pending';
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),offer_id uuid NOT NULL REFERENCES offers(id),author_id text NOT NULL REFERENCES profiles(id),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS enquiries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL,company text NOT NULL DEFAULT '',message text NOT NULL,status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','in_progress','resolved')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log(id bigserial PRIMARY KEY,actor_id text NOT NULL REFERENCES profiles(id),action text NOT NULL,entity text NOT NULL,entity_id text NOT NULL,details text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits(key text NOT NULL,bucket timestamptz NOT NULL,count integer NOT NULL,PRIMARY KEY(key,bucket));
CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY,applied_at timestamptz NOT NULL DEFAULT now());
INSERT INTO schema_migrations(version) VALUES ('001_platform') ON CONFLICT DO NOTHING;
COMMIT;
